// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0); // plain EOA counterparty: low-level call succeeds
        bound(amount, 1, type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll(); // must succeed and consume the credit

        // General rule: once all credit has been withdrawn, a repeat withdrawAll
        // by the same actor must complete WITHOUT reverting.
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(ok);
    }
}
